import sys
import functools

def solve(n):
    if n == 1:
        return 1

    phi = [1] * n
    for i in range(2, n):
        phi[i] = (phi[i-1] * (i-1)) % (10**9 + 7)

    dp = [None] * n
    for i in range(n):
        if i == 0:
            dp[i] = [[1,0]] * phi[0]
        elif i == 1:
            dp[i] = [[1,0], [1,phi[1]]]
        else:
            vals = [[1,0]] * phi[i]
            for j in range(1, i):
                vals[j] = vals[j-1]
            vals[0] = [phi[i-1], 0]
            vals[-1] = [0, (n-i) * (phi[i-1] - 1)] % (10**9 + 7)
            dp[i] = vals

    return functools.reduce(lambda a, b: [x[1] for x in a] + [x[0] for x in b], dp[-1], []) % (10**9 + 7)

