from collections import defaultdict

def min_transformations(A, B):
    if len(A) != len(B):
        return -1
    diff = defaultdict(int)
    for a, b in zip(A, B):
        if a != b:
            diff[a] += 1
    for a, b in zip(A, B):
        if diff[a] and diff[b] and a != b:
            return -1
    return sum(diff.values())

