import sys
from typing import List
from math import sqrt

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_parent(u: int) -> int:
    if parent[u] == u:
        return u
    parent[u] = find_parent(parent[u])
    return parent[u]

def union_sets(x: int, y: int):
    parent[find_parent(x)] = find_parent(y)

def max_prime_subtrees(N: int, vals: List[int]) -> List[tuple]:
    parent = list(range(N + 1))
    ans = []

    for i in range(N - 1):
        min_prime = sys.maxsize
        min_index = -1
        for j in range(i + 1, N):
            for k in range(j, N):
                subtree_sum = vals[find_parent(i)] + vals[find_parent(j)] + vals[find_parent(k)]
                if is_prime(subtree_sum) and subtree_sum < min_prime:
                    min_prime = subtree_sum
                    min_index = k

        ans.append((i + 1, min_index + 1))
        union_sets(i + 1, min_index + 1)

    return ans

