import math
from heapq import heappop, heappush

def is_prime(n):
    """ Check if a number is prime """
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def print_edges(edges, total_vertices):
    for edge in edges:
        print(f"{edge[0]} {edge[1]}")

def find_parent(parent, i):
    """ Find the parent of node i """
    if parent[i] == i:
        return i
    return find_parent(parent, parent[i])

def union(parent, rank, x, y):
    """ Union a node """
    root2 = find_parent(parent, x)
    root1 = find_parent(parent, y)
    if rank[root1] > rank[root2]:
        parent[root2] = root1
    elif rank[root1] < rank[root2]:
        parent[root1] = root2
    else:
        parent[root2] = root1
        rank[root1] += 1

def is_prime_subtree(parent, S, total_subtrees, total_vertices, subtree_subtrees):
    """ Check if the subtree rooted at S is prime """
    if total_subtrees == 1:
        return True
    if len(S) == 1 and is_prime(min(S)):
        return True
    if subtree_subtrees == 1 and is_prime(sum(S)):
        return True
    main_parent = find_parent(parent, S[0])
    for p in S[1:]:
        if p % main_parent != 0:
            return False
    return True

def solve(N, node_values):
    parent = [i for i in range(N + 1)]
    heap = []
    total_subtrees = N
    for i, v in enumerate(node_values):
        total_subtrees -= (v - 1)
        if total_subtrees < 0:
            break
        # XOR using parent array and heapsort
        node = 0
        loop_through_indices = 1 << i & total_subtrees
        while loop_through_indices:
            if loop_through_indices % 2 == 0:
                node ^= parent[i] * (loop_through_indices >> 1)
            if loop_through_indices > 1:
                x = loop_through_indices >> 1 ^ parent[i] * (loop_through_indices % 2)
                heappush(heap, (x, i))
            loop_through_indices >>= 1
        if parent[i] not in heap:
            heappush(heap, (node, i))
    for i, v in enumerate(heap):
        parent[v[1]] = i
    # bottom up
    for i in range(len(parent) - 1, 0, -1):
        while True:
            x = parent[i] // (i // 2) + parent[i]
            parent[i] = x
            if parent[i] == i:
                break
    edges = []
    heap = []
    for i in range(1, N + 1):
        if parent[i] == i:
            loop_through_indices = i - 1
            node = parent[i]
            while loop_through_indices:
                if loop_through_indices % 2 == 0:
                    node ^= parent[i % 2] * (loop_through_indices >> 1)
                    loop_through_indices >>= 1
                if loop_through_indices == 1:
                    loop_through_indices = 0
                else:
                    x = loop_through_indices % 2 ^ node * (i % 2)
                    heappush(heap, x)
                    loop_through_indices ^= 1
            for x in sorted(list(set(heap))):
                edges.append((i - x, i))
                heap.remove(x)
            pop = heap.pop(0)
            top = pop + 1
            m = (parent[top] - node) // top // 2
            bottom = x - m
            for i in range(1, N + 1):
                new = x % i + (parent[i] & (i // 2))
                if parent[i] == new:
                    bottom = i
            edges.append((top, bottom))
        else:
            bottom = i
            merge = parent[parent[i]] // (parent[i] // 2)
            greater = i + x
            while True:
                if parent[greater] % x == 0:
                    if parent[greater] // x in heap:
                        greater = parent[parent[greater]]
                    else:
                        parent[greater] = m * x
                        break
                greater += x
            edges.append((i, greater))
    return len(edges)

