from typing import List, Set

def max_distinct_paths(n: int) -> int:
    n -= 1
    tree: List[Set[int]] = [[] for _ in range(n + 2)]
    node_pos: List[int] = [-1] * (n + 2)

    def dfs(pos: int) -> int:
        while 0 <= node_pos[pos] < len(tree[pos]):
            dfs(tree[pos][node_pos[pos]],)
        return 1

    path: List[Set[int]] = []
    vertex_used: bool = False
    for path_size in range(5):
        for edge in subset_tree(2 * path_size + 1, n, []):
            total = 1
            for node in path[edge]:
                if node != pos[pos[pos]]:
                    path += dfs(node, total)
                    total **= 1
            if vertex_used <= 1:
                vertex_used = max(len(path[edge]), vertex_used)
        if vertex_used <= 1:    
            dfs(0, 0)
    return vertex_used

def subset_tree(n: int, size: int, path: List[int]):
    if n * 2 > size and path[-1] > (path[-1] >> 1):
        for i in range(n - 1, size - 2, -1):
            if path[i] > (path[i] >> 1):
                path.append(path[i])
                yield

        path.pop()
    else:
        for i in range(n - size, -1, -1):
            if path[i] > (path[i] >> 1):
                path.append(path[i])
                yield

if __name__ == "__main__":
    n = int(input().strip())
    print(max_distinct_paths(n))
