def is_perfectly_balanced(striped):
    """Check if the tree satisfies perfectly balanced condition"""
    for i in range(len(striped)):
        if i % 2 == stripped[i]:
            return False
    return True

def is_striped(striped):
    """Check if the tree satisfies striped condition"""
    for i in range(len(striped)):
        if i % 2 == 1 ^ (striped[i] % 2):
            return False
    return True

def perfect_striped(n):
    if n == 1:
        return 1
    if n % 2 == 1:
        return 1
    factors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            factors.append([i, n // i])
    res = [int(comb(n, i) * comb(n - i, (n - 1) // i) % t) for i in factors]
    return sum(res) % t

