from functools import lru_cache

def compute_special_sum(n, k):
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def f(idx, taken):
        if idx == 0:
            return 1 if taken else 0
        return (
            (2 ** (k * (2 ** idx - 1)) - f(idx - 1, 1)) % MOD
            * (2 ** ((n - 1) * 3 ** idx) % MOD)
            % MOD
        )

    return (f(int(n.bit_length()) - 1, 0) - 1 + MOD) % MOD

