@lru_cache(maxsize=None)
def comb(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def possible_arrangements(n, slots):
    if n == 0:
        return []

    prev = 0
    total = 0

    for _, idx in enumerate(slots):
        if idx == 0:
            prev = idx
            continue

        if slots[0] == 0:
            total += comb(n, prev)
        else:
            slots[0] -= 1

        total = (total + comb(n - 1, prev)) % MOD
        prev = idx

    return total

