import sys

def max_score(nums):
    n = len(nums)
    prefix_sums = [0]
    suffix_sums = [0]
    nums.sort()

    # Calculate prefix sums
    for num in nums:
        prefix_sums.append(prefix_sums[-1] + num)

    # Skip 0s in prefix_sums
    for i in range(n, 0, -1):
        if prefix_sums[i] >= 0:
            break
        prefix_sums.pop()

    # Calculate suffix sums, but up to i-1 as nums is sorted
    for i in range(n-1, 0, -1):
        if prefix_sums[i] >= 0:
            break
        suffix_sums.insert(0, suffix_sums[0] + nums[i])

    # Skip the unwanted 0s in the suffixes
    for i in range(n, len(suffix_sums), n):
        if suffix_sums[i] < 0:
            break

    # Concatenate the prefix and suffix and replace 0s
    for i in range(n):
        if prefix_sums[i] == 0:
            prefix_sums[i] = nums[i]
            break

    return max(prefix_sums + suffix_sums), nums

def main():
    nums = list(map(int, input().split()))
    max_score, optimal_nums = max_score(nums)
    print(max_score)

if __name__ == "__main__":
