def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def maximize_prime_subtrees(V, N):
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            if is_prime(sum(V)):
                edges.append((i + 1, j + 1))
            else:
                for k in range(2, min(i + 1, j)):
                    if (V[i] + V[j] - V[k] % (V[i] + V[j] - V[k])) % 2 == 0:
                        if is_prime(V[i] + V[j] - V[k] // 2 + 1):
                            edges.append((i + 1, k + 1))
                            edges.append((k + 1, j + 1))
                        if (V[i] + V[j] - V[k] % (V[i] + V[j] - V[k])) % 2 == 1:
                            if is_prime(V[i] + V[j] - V[k] // 2 + 3):
                                edges.append((i + 1, j + 1))
                                edges.append((k + 1, k + 1))
    return edges

def format_edges(edges):
