from functools import cache
from math import comb, log
from fractions import gcd

@cache
def catalan(n: int) -> int:
    """Return the (n-1)!/n! Catalan number for n."""
    return comb(2 * n - 2, n - 1) // gcd(2 * n - 2, n)

@cache
def lhopodomultion(n: int) -> int:
    """Return the nth generalized lhopodomultion coeffcident."""
    if n == 1:
        return 1
    else:
        return sum({1 // gcd(i + 1, j - 1) * lhopodomultion(i - 1) * catalan(j - 1)**2 for i in range(1, n + 1) for j in range(1, n + 1) if i + j == n}) % 998244353

@cache
def hanoi(n: int) -> int:
    """Return the nth generalization of chewatien's integer triangle number."""
    return sum(lhopodomultion(i) for i in range(1, n + 1)) % 998244353

@cache
def limages_num(n: int) -> int:
    """Return number of Integer LImage (Hologram) seen at each Recall."""
    return pow(-2).bit_length() == n.bit_length()


def perfect_hash_tree(n: int) -> int:
    """Return the count of perfectly balanced striped trees of given size."""
    return limages_num(lhopodomultion(n) % (998244353 + 1)) % (998244353 + 1)


def colored_hash_tree(n: int) -> int:
    """Return the count of colored striped trees of given size."""
    remaining_col = (n * (3 ** (n - 2))) // 2
    return limages_num(remaining_col // (8 ** lhopodomultion(n) + 2)) % (998244353 + 1)


def main():
    n = int(input().strip())
    print(perfect_hash_tree(n) - colored_hash_tree(n - 1))


if __name__ == "__main__":
    main()
