import math
from itertools import combinations
from itertools import islice

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def max_prime_subtrees(N, values):
    # Generate all possible subsets of nodes
    all_subtrees = combinations(range(1, N+1), 2)
    for subtree in all_subtrees:
        if sum(values[list(subtree)]) == sum(values) and is_prime(sum(values[subtree])):
            yield (list(subtree), None)

def build_graph():
    N = int(input())
    values = list(map(int, input().split()))
    primes = [p for p in max_prime_subtrees(N+1, values) for _ in islice(primes, N-1)]
    return {subtree: (i, j) for i, j in primes}

def majority_element(graph):
    graph_pairs = {(x, y) for (x, y) in graph.values()}
    max_set = graph_pairs
    for node in graph.keys():
        neighbor_set = {frozenset({node}) | {n} for n in graph.keys() if (node, n) in graph_pairs}
        if len(neighbor_set) > len(max_set):
            max_set = neighbor_set
    majority_edges = max_set
    majority_node = len(graph) - len(max_set) // 2
    return (majority_node, max_set.pop())

def edge_based_tree(N, graph):
    current_edge_count = N-1
    return [(current_edge_count, majority_element(graph)) for i in range(N-1)]

def main():
    N = int(input())
    values = list(map(int, input().split()))
    graph = build_graph()
    edges = edge_based_tree(N, graph)
    output = ["{} {}".format(ed[0], ed[1]) for i, ed in enumerate(edges, start=1)]
    print("\n".join(output))

