import bisect

def update_range(x, y, seq, query_handlers):
    # Process the existing segment after the update
    idx = bisect.bisect_right(seq, x-1)
    new_start, new_end = idx, idx
    if 0 < idx and abs(query_handlers[(idx-1,y)]) >= abs(query_handlers[(idx,y)]):
        new_start = -1
        idx -= 1
    if idx < len(seq) and abs(query_handlers[(x, idx+1)]) >= abs(query_handlers[(x, idx)]):
        new_end = -1

    # Bring segment to pos (x,y)
    for q in range(idx, x):
        while 0 <= seq[q] < new_start:
            seq.pop(q-idx)
        while new_start <= seq[q] < y:
            seq.insert(q-idx, query_handlers[(q,y)] * (-1))
        if x < 0 and seq[q] < x:
            seq.insert(q-idx, x)
    for q in range(idx, y):
        while 0 <= seq[q] < new_end:
            seq.pop(q-idx)
        while new_end <= seq[q] < len(seq):
            q += 1
            if seq[q] == 0:
                break
            else:
                seq.insert(q-idx, -1)
            seq[::-1].pop(0)
    for q in range(q+1, -1, -1):
        if seq[q] < 0 and seq[q] != seq[-1]:
            seq.insert(-(q-idx), 0)

def find_max_sum_range(seq, x, y, k):
    badness_after = [0 for i in range(len(seq)+1)]
    badness_at = [0 for i in range(len(seq)+1)]
    for i in range(1, len(badness_after)):
        badness_after[i] = max(badness_after[i], badness_at[i-1])
        while 0 <= seq[i-1] > badness_after[(badness_after.bisect_left(seq[i-1]))]:
            badness_after[(badness_after.bisect_left(seq[i-1])) - 1] += seq[i-1]
        k -= abs(badness_after[bisect.bisect_right(badness_after, badness_after.bisect_left(seq[i-1]))])
    max_sum = badness_after[bisect.bisect_right(badness_after, 0)]
    if k == 0:
        return max_sum
    badness_at[k] = max(badness_after.bisect_right(0))
    while 0 <= seq[badness_at[k]] <= badness_after[(badness_after[bisect.bisect_left(badness_after, badness_after.bisect_right(badness_at[k]))) - 1]]:
        badness_at[k] -= seq[badness_at[k]]
    return max(max_sum, badness_at[k])

