from itertools import permutations

def find_puzzle_pieces(vertices, pieces):
    cut_indices = []
    for piece in pieces:
        vertices[0], vertices[1], vertices[-1] = vertices[-1], vertices[0], vertices[1]
        cut_indices.append(vertices.index(piece[0]) - 1)

    return cut_indices

def permute_and_cut(pieces, order):
    cut_indices = find_puzzle_pieces(pieces, order)
    return cut_indices

def check_solution(vertices, cut_indices):
    remaining_vertices = list(range(1, len(vertices)))
    n = len(vertices)
    temp = list(permute_and_cut(cut_indices, vertices))

    cut_indices.sort()
    cut_segments = []
    # Construct the segments of cuts
    segments_full = {}
    for segment_index, (i, j) in enumerate(zip(cut_indices[:-1], cut_indices[1:])):
        segments_full[segment_index] = min(i, j)
    for segment_index in range(len(cut_indices)):
        if segments_full[segment_index] in cut_segments and segments_full[segment_index] >= segment_index:
            break
        else:
            cut_segments.append(segments_full[segment_index])
    return cut_segments[-1] == len(cut_indices)

