import random

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_prime_subtrees(n, values):
    for i in range(n, 1, -1):
        sums = [0] * (n - i + 1)
        for j in range(i - 1):
            if is_prime(sum(values[j:j + i - 1])):
                sums[j] = 1
        if sums[0] == 1:
            return [i], sums
    return None

