import sys

def is_good_game(n, k, coins):
    if k + 1 > n:
        return -1  # Not possible to give coins to everyone

    for i in range(k + 2):
        M = 10**9 + 1
        rounds = 0

        # Calculate the coins for each pirate
        for j in range(k + 2):
            if i != j:
                if j == 0:
                    M = min(M, j + 1 - coins[j] // (k + 1) * (k + 1))
                elif j == k + 1:
                    M = min(M, n - j - (coins[j] - coins[0]))
                else:
                    M = min(M, coins[j] - coins[j - 1] // (j - k))

        if M == 10**9 + 1:
            return -1  # No valid permutations exist
        else:
            rounds = (n - i - 1) // (n - 2) + 1

    return True

