import sys
import math

def can_finite_end(n, k, coins):
    start_k = {}
    for coin in coins:
        start_k[coin[0]] = start_k.get(coin[0], 0) + coin[1]

    if sum(a >= 2 for a in start_k.values()) > n - k or sum(a <= 1 for a in start_k.values()) == n:
        return 1

    max_total = max(start_k.values())
    possible = []

    for total, nums in start_k.items():
        nums.sort()
        if total < max_total and num + 3 < 1e6 for num in nums):
            possible.append((k, total))

    for k, total in possible:
        if math.ceil(total * 1.01) <= k:
            return 1

    return -1

