def maximize_simple_paths(n):
    # Initialize the graph as a dictionary of sets
    graph = {i: set() for i in range(1, n + 1)}
    # Read the edges of the graph
    for _ in range(n - 1):
        v, u = map(int, input().split())
        graph[v].add(u)
        graph[u].add(v)

    # Function to calculate the number of simple paths from source to destination
    def numSimplePaths(src, dest, visited, parent):
        visited[src] = True
        num_paths = 1
        for neighbor in graph[src]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                continue
            num_paths += numSimplePaths(neighbor, dest, visited, src)
        return num_paths + 1  # Adding the start node to the path

    # Initialize the visited array
    visited = [False] * (n + 1)
    # Try adding edges between all pairs of graph vertices
    max_paths = 0  
    for v in range(1, n + 1):
        for u in range(1, n + 1):
            if v != u and not visited[v] and not visited[u]:
                max_paths = max(max_paths, numSimplePaths(v, u, visited, -1))

    return max_paths

# Example usage
n = int(input())
print(maximize_simple_paths(n))
