from math import pow

def expMod(b, k, mod):
    result = 1
    base = b % mod

    while k:
        if k & 1:
            result = result * base % mod
        base = base * base % mod
        k >>= 1
    return result

def solve(n, k):
    if k == 0:
        return 1 % (10**9 + 7)
    base = (n % (10**6+1)) % (10**9+7)
    base_inverse = pow(base, 1000000007 - 2, 1000000007)
    return expMod(base_inverse, k % 2, (10**9 + 7)) * expMod(base, 2**(k - 1) % 2, (10**9 + 7)) % (10**9 + 7)

n, k = map(int, input().split())
print(solve(n, k))
